:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-surface: #f5f5f2;
  --color-frosted-glass: #ffffffe6;
  --color-forest-vault: #203524;
  --color-moss-panel: #2d4c33;
  --color-fog-scrim: #11110d80;
  --color-ink: #11110d;
  --color-ash-border: #d5d5d2;
  --color-mist-hairline: #11110d1c;
  --color-pebble-wash: #11110d0d;
  --color-keylime-signal: #d1f470;
  --color-sprout-ink: #70a32a;
  --color-forest-pulse: #4e8336;

  /* Typography — Font Families */
  --font-vanilla-sans: "Vanilla Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 14px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 15px;
  --leading-caption: 1.4;
  --tracking-caption: 0px;
  --text-body: 16px;
  --leading-body: 1.625;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.556;
  --tracking-body-lg: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.45;
  --tracking-subheading: 0px;
  --text-heading-sm: 33px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: 0px;
  --text-heading: 53px;
  --leading-heading: 1.15;
  --tracking-heading: 0px;
  --text-heading-lg: 72px;
  --leading-heading-lg: 1.1;
  --tracking-heading-lg: 0px;
  --text-display: 85px;
  --leading-display: 1.05;
  --tracking-display: 0px;
  --tracking-eyebrow: 0.75px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-72: 72px;
  --spacing-96: 96px;
  --spacing-104: 104px;
  --spacing-120: 120px;

  /* Layout */
  --layout-page-max-width: 1600px;
  --layout-section-gap: 104px;
  --layout-card-padding: 32px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 20px;
  --radius-3xl: 32px;
  --radius-3xl-2: 40px;
  --radius-full: 100%;

  /* Named Radii */
  --radius-cards: 40px;
  --radius-sections: 32px;
  --radius-inner-tiles: 20px;
  --radius-buttons: 16px;
  --radius-small-cards: 16px;
  --radius-inputs: 12px;
  --radius-small-elements: 8px;
  --radius-nav: 4px;
  --radius-avatars: 100%;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px #d5d5d2;
  --shadow-subtle-2: inset 0 2px 0 0 #d5d5d2;
  --shadow-md: 0 8px 24px 0 rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 20px 30px 0 rgba(23, 73, 77, 0.15);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-surface: #f5f5f2;
  --surface-frosted-glass: #ffffffe6;
  --surface-forest-vault: #203524;
  --surface-ink: #11110d;
}

